INSERT [dbo].[AutomatedJobs] ([Id], [Name], [IterationMinutes], [SourceKey], [UserId], [SqlValue], [IsEnabled], [IsDeleted], [CreatedAtUtc], [UpdatedAtUtc], [LastCalledAtUtc], [LastScheduledAtUtc], [LastResult]) VALUES (1, N'کال تستی یک جدول', 100, N'UiLog', 2, N'select top 1 * from dbo.ResponseUiLog', 0, 0, CAST(N'2026-10-12T11:45:43.2697803+00:00' AS DateTimeOffset), CAST(N'2026-10-13T04:51:22.6306171+00:00' AS DateTimeOffset), CAST(N'2026-10-13T04:51:09.4348917+00:00' AS DateTimeOffset), CAST(N'2026-10-13T04:51:00.0000000+00:00' AS DateTimeOffset), N'موفق')
GO
INSERT [dbo].[AutomatedJobs] ([Id], [Name], [IterationMinutes], [SourceKey], [UserId], [SqlValue], [IsEnabled], [IsDeleted], [CreatedAtUtc], [UpdatedAtUtc], [LastCalledAtUtc], [LastScheduledAtUtc], [LastResult]) VALUES (2, N'دریافت ریپورت لاگ', 60, N'SrLog', 2, N'SELECT
    DATEADD(HOUR, DATEDIFF(HOUR, 0, CallTime), 0) AS [Hour],
    COUNT_BIG(*) AS TotalCount,
    SUM(CASE
        WHEN ErrorCode = 0 THEN 1 ELSE 0
    END) AS SuccessCount,
    SUM(CASE
        WHEN ErrorCode <> 0 AND Exception IS NULL THEN 1 ELSE 0
    END) AS BusinessErrorCount,
    SUM(CASE
        WHEN ErrorCode <> 0 AND Exception IS NOT NULL THEN 1 ELSE 0
    END) AS SystemExceptionCount
FROM dbo.Response
WHERE CallTime >= DATEADD(DAY, -7, GETDATE())
  AND CallTime < GETDATE()
GROUP BY
    DATEADD(HOUR, DATEDIFF(HOUR, 0, CallTime), 0)
ORDER BY
    [Hour] DESC', 0, 0, CAST(N'2026-10-12T13:26:09.5096026+00:00' AS DateTimeOffset), CAST(N'2026-10-12T13:35:16.3463156+00:00' AS DateTimeOffset), CAST(N'2026-10-12T13:35:19.9750721+00:00' AS DateTimeOffset), NULL, N'موفق')
GO
SET IDENTITY_INSERT [dbo].[AutomatedJobs] OFF
